      // P2 历史曲线：低频随轮询拉取（进程内 RPC 开销可忽略；失败静默保留旧曲线）
      try {
        var h = await host.call('labMonitor.history', { sinceMs: HIST_SINCE_MS, bucketMs: HIST_BUCKET_MS })
        if (alive && h && Array.isArray(h.points) && h.points.length) setHist(h.points)
