      ? React.createElement('div', { style: { fontSize: 12, color: C.label2 } },
          '实验 ' + (s.experiment.runId || '-') + ' [' + (s.experiment.state || '-') + ']' +
          (s.experiment.cmd ? ' · ' + s.experiment.cmd : '') +
